using Azure.Storage.Blobs;using Azure.Storage.Blobs.Models;using Microsoft.AspNetCore.Http;using Microsoft.Extensions.Configuration;namespace RaceDay.MVC.Services;public interface IBlobStorageService{Task<string> UploadAsync(IFormFile file, string containerName);}public class BlobStorageService : IBlobStorageService{private readonly BlobServiceClient _blobServiceClient;public BlobStorageService(IConfiguration configuration){var conn = configuration["AzureBlobStorage:ConnectionString"];if(string.IsNullOrEmpty(conn))conn="";_blobServiceClient=new BlobServiceClient(conn);}public async Task<string> UploadAsync(IFormFile file, string containerName){var container=_blobServiceClient.GetBlobContainerClient(containerName);await container.CreateIfNotExistsAsync(PublicAccessType.Blob);var blobName=Guid.NewGuid().ToString()+Path.GetExtension(file.FileName);var blob=container.GetBlobClient(blobName);await using var stream=file.OpenReadStream();await blob.UploadAsync(stream,new BlobHttpHeaders{ContentType=file.ContentType});return blob.Uri.ToString();}}